"use client";

import { useState, useTransition } from "react";
import { CheckCircle2, Loader2, RefreshCw, XCircle } from "lucide-react";
import { generateFolderQuiz } from "@/lib/actions";
import type { FolderQuizQuestion } from "@/lib/settings";

/**
 * Folder-wide quiz: generated by the server across every document in the
 * folder (and its subfolders, per the user's settings), then answered here.
 * Each question carries its sources so provenance is visible.
 */
export function FolderQuizRunner({
  folderId,
  documentCount,
  initialQuiz,
}: {
  folderId: string;
  documentCount: number;
  initialQuiz: FolderQuizQuestion[] | null;
}) {
  const [quiz, setQuiz] = useState<FolderQuizQuestion[] | null>(initialQuiz);
  const [answers, setAnswers] = useState<Record<number, number>>({});
  const [error, setError] = useState<string | null>(null);
  const [isPending, startTransition] = useTransition();

  function generate(regenerate: boolean) {
    setError(null);
    startTransition(async () => {
      try {
        const result = await generateFolderQuiz(folderId, regenerate);
        setQuiz(result);
        setAnswers({});
      } catch (e) {
        setError(
          e instanceof Error ? e.message : "Could not generate the quiz."
        );
      }
    });
  }

  if (!quiz) {
    return (
      <div className="rounded-xl border border-[#dadce0] bg-white p-6 text-center dark:border-white/10 dark:bg-slate-900">
        <p className="text-sm text-[#3c4043] dark:text-slate-200">
          {documentCount === 0
            ? "This folder has no documents yet. Add or import a few, then come back."
            : `Generate a quiz across ${documentCount} document${documentCount === 1 ? "" : "s"} in this folder.`}
        </p>
        {error && (
          <p className="mt-3 text-sm text-red-600 dark:text-red-400">{error}</p>
        )}
        <button
          type="button"
          onClick={() => generate(false)}
          disabled={isPending || documentCount === 0}
          className="mt-4 inline-flex h-10 items-center gap-2 rounded-full bg-slate-900 px-5 text-sm font-medium text-white transition hover:bg-slate-700 disabled:opacity-60 dark:bg-white dark:text-slate-900 dark:hover:bg-slate-200"
        >
          {isPending ? (
            <Loader2 className="h-4 w-4 animate-spin" />
          ) : null}
          {isPending ? "Generating…" : "Generate quiz"}
        </button>
      </div>
    );
  }

  const answered = Object.keys(answers).length;
  const correct = quiz.reduce(
    (n, q, i) => n + (answers[i] === q.answerIndex ? 1 : 0),
    0
  );

  return (
    <div>
      <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
        <p className="text-sm text-[#5f6368] dark:text-slate-400">
          {answered === 0
            ? `${quiz.length} questions · answer to see your score`
            : `${correct} / ${quiz.length} correct`}
        </p>
        <button
          type="button"
          onClick={() => generate(true)}
          disabled={isPending}
          className="inline-flex h-9 items-center gap-2 rounded-full border border-slate-900/15 px-4 text-sm font-medium text-slate-700 transition hover:bg-slate-900/5 disabled:opacity-60 dark:border-white/15 dark:text-slate-200 dark:hover:bg-white/5"
        >
          {isPending ? (
            <Loader2 className="h-4 w-4 animate-spin" />
          ) : (
            <RefreshCw className="h-4 w-4" />
          )}
          Regenerate
        </button>
      </div>

      {error && (
        <p className="mb-3 text-sm text-red-600 dark:text-red-400">{error}</p>
      )}

      <div className="space-y-4">
        {quiz.map((q, qi) => {
          const chosen = answers[qi];
          const isAnswered = chosen !== undefined;
          return (
            <div
              key={qi}
              className="rounded-xl border border-[#dadce0] bg-white p-4 dark:border-white/10 dark:bg-slate-900"
            >
              <p className="text-sm font-medium text-[#202124] dark:text-slate-100">
                {qi + 1}. {q.question}
              </p>
              {q.source && (
                <p className="mt-1 text-xs text-[#5f6368] dark:text-slate-500">
                  Source: {q.source}
                </p>
              )}
              <div className="mt-3 space-y-1">
                {q.options.map((opt, oi) => {
                  const correctOption = oi === q.answerIndex;
                  const picked = chosen === oi;
                  let cls =
                    "text-[#3c4043] hover:bg-black/[0.04] dark:text-slate-200 dark:hover:bg-white/10";
                  if (isAnswered) {
                    if (correctOption)
                      cls =
                        "bg-emerald-50 text-emerald-700 dark:bg-emerald-500/10 dark:text-emerald-300";
                    else if (picked)
                      cls =
                        "bg-red-50 text-red-600 dark:bg-red-500/10 dark:text-red-400";
                    else cls = "text-slate-400 dark:text-slate-500";
                  }
                  return (
                    <button
                      key={oi}
                      type="button"
                      disabled={isAnswered}
                      onClick={() =>
                        setAnswers((a) => ({ ...a, [qi]: oi }))
                      }
                      className={`flex w-full items-center justify-between gap-2 rounded-md px-3 py-2 text-left text-sm ${cls}`}
                    >
                      <span>{opt}</span>
                      {isAnswered && correctOption && (
                        <CheckCircle2 className="h-4 w-4 shrink-0" />
                      )}
                      {isAnswered && picked && !correctOption && (
                        <XCircle className="h-4 w-4 shrink-0" />
                      )}
                    </button>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
